docker run --rm -v /workspace/01-frontend:/w -w /w node:20-bookworm node -e "
const fs=require('fs');
const ws=['shared','shell','mfe-fp','mfe-kp','mfe-mp','mfe-verwaltungsakt','mfe-vp','mfe-ws','mfe1','mfe-ewm'];
const missing=[];
for (const w of ws) { try{ JSON.parse(fs.readFileSync(w+'/package.json')); }catch(e){ missing.push(w+': '+e.message); } }
console.log(missing.length? 'BAD: '+JSON.stringify(missing): 'all workspace package.json valid');
const l=JSON.parse(fs.readFileSync('package-lock.json','utf8'));
const keys=Object.keys(l.packages||{});
console.log('lockfileVersion:', l.lockfileVersion);
console.log('hey-api entries:', keys.filter(k=>k.includes('hey-api')).slice(0,8));
console.log('xlsx entries:', keys.filter(k=>k.endsWith('xlsx')).slice(0,8));
"
